#!/usr/bin/env python3
# Standard-monomial check for the general-n family (unreviewed). Pure Python, no packages.
# For n=3..6: monomials not divisible by A*B_i, E_i*B_i, B_i*B_j, A^2*C map injectively onto the
# semigroup S_n generated by the 2n+2 vectors, up to the stated weight; and the decoding rule inverts it.
import itertools, sys
def gens_vec(n):
    V=[tuple([0]*n+[-1])]
    for i in range(n): V.append(tuple(1 if j==i else 0 for j in range(n))+(0,))
    for i in range(n): V.append(tuple(0 if j==i else 1 for j in range(n))+(1,))
    V.append(tuple([1]*n+[2])); return V
def wt(b): return sum(b[:-1])-b[-1]
def check(n,WB):
    V=gens_vec(n); nv=len(V); vw=[wt(v) for v in V]          # variable order: A, E0..E(n-1), B0..B(n-1), C
    A=0; E=list(range(1,n+1)); B=list(range(n+1,2*n+1)); C=2*n+1
    def ev(*pairs):
        u=[0]*nv
        for i,e in pairs: u[i]+=e
        return tuple(u)
    Lg=[ev((A,1),(B[i],1)) for i in range(n)]+[ev((E[i],1),(B[i],1)) for i in range(n)]+[ev((B[i],1),(B[j],1)) for i in range(n) for j in range(i+1,n)]+[ev((A,2),(C,1))]
    std=[]
    def rec(i,left,cur):
        if i==nv:
            u=tuple(cur)
            if not any(all(x<=y for x,y in zip(g,u)) for g in Lg): std.append(u)
            return
        for e in range(left//vw[i]+1):
            cur.append(e); rec(i+1,left-e*vw[i],cur); cur.pop()
    rec(0,WB,[])
    deg=lambda u: tuple(sum(u[i]*V[i][c] for i in range(nv)) for c in range(n+1))
    degs=[deg(u) for u in std]
    S={(0,)*(n+1)}; fr=set(S)
    while fr:
        new=set()
        for b in fr:
            for v in V:
                c=tuple(x+y for x,y in zip(b,v))
                if wt(c)<=WB and c not in S: new.add(c)
        S|=new; fr=new
    def decode(b):
        x=b[:n]; k=b[n]; u=[0]*nv
        pos=[i for i in range(n) if k-2*x[i]>0]
        if pos:
            i=pos[0]; c=x[i]; m=k-2*c
            u[B[i]]=m; u[C]=c
            for j in range(n):
                if j!=i: u[E[j]]=x[j]-c-m
        else:
            if k>=1: c=(k+1)//2; a=2*c-k
            else: c=0; a=-k
            u[A]=a; u[C]=c
            for j in range(n): u[E[j]]=x[j]-c
        return tuple(u)
    dec_ok=all(min(decode(b))>=0 and not any(all(x<=y for x,y in zip(g,decode(b))) for g in Lg) and deg(decode(b))==b for b in S)
    return len(std), len(set(degs))==len(degs), set(degs)==S, dec_ok
ok=True
for n,WB in ((3,14),(4,13),(5,12),(6,11)):
    cnt,inj,onto,dec=check(n,WB)
    good=inj and onto and dec; ok&=good
    print(("PASS" if good else "FAIL"),"n=%d weight<=%d: %d standard monomials, injective=%s, image=S_n=%s, decode inverts=%s"%(n,WB,cnt,inj,onto,dec),flush=True)
print("ALL PASS" if ok else "SOME CHECK FAILED"); sys.exit(0 if ok else 1)
